import Home from './pages/Home';
import AddApp from './pages/AddApp';
import ContestWinners from './pages/ContestWinners';
import AdminDashboard from './pages/AdminDashboard';
import Login from './pages/Login';
import Register from './pages/Register';
import DebugPage from './pages/DebugPage';
import Layout from './components/Layout';
// Auth and Contest Providers/Context
import { useAuth } from './contexts/AuthContext';
import { ContestProvider } from './contexts/ContestContext';

/**
 * A PrivateRoute wrapper to gate protected routes.
 * Only renders the children if user is authenticated.
 * Otherwise, redirects to /login.
 */
// PUBLIC_INTERFACE
function PrivateRoute({ children }) {
  const { user } = useAuth();
  if (!user) {
    return <Navigate to="/login" replace />;
  }
  return children;
}

// PUBLIC_INTERFACE
function AppRouter() {
  return (
    <Router>
      <Routes>
        {/* Unauthenticated routes: No context providers */}
        <Route element={<Layout />}>
          <Route path="/login" element={<Login />} />
          <Route path="/register" element={<Register />} />

          {/* All protected/authenticated routes wrapped with ContestProvider */}
          <Route
            element={
              <PrivateRoute>
                <ContestProvider>
                  <Layout />
                </ContestProvider>
              </PrivateRoute>
            }
          >
            <Route index element={<Home />} />
            <Route path="/add" element={<AddApp />} />
            <Route path="/winners" element={<ContestWinners />} />
            <Route path="/admin" element={<AdminDashboard />} />
            <Route path="/debug" element={<DebugPage />} />
            {/* Add more protected routes here */}
          </Route>

          {/* Fallback: redirect everything else to login */}
          <Route path="*" element={<Navigate to="/login" replace />} />
        </Route>
      </Routes>
    </Router>
  );
}

